'use client';

import { useEffect, useState } from 'react';
import { planningAlerts } from '../components/agri/planning';
import type { Science, Forecast, Observation, Bootstrap, BusinessRecord, RecordKind, Role } from '../lib/contracts';

type View='previsions'|'comparaison'|'simulation'|'collecte'|'recoltes'|'fiche'|'gestion'|'import';
const views:{id:View;label:string;icon:string}[]=[{id:'previsions',label:'Prévisions',icon:'leaf'},{id:'comparaison',label:'Comparer les campagnes',icon:'chart'},{id:'simulation',label:'Simuler une récolte',icon:'calc'},{id:'collecte',label:'Organiser la collecte',icon:'truck'},{id:'recoltes',label:'Récoltes réalisées',icon:'basket'},{id:'fiche',label:'Fiche de campagne',icon:'file'}];
const cropsFR:Record<string,string>={Maize:'Maïs',Rice:'Riz',Sorghum:'Sorgho',Millet:'Mil',Cassava:'Manioc',Yam:'Igname',Beans:'Haricot',Groundnuts:'Arachide',Cowpea:'Niébé',Soybean:'Soja'};
const fr=(s:string)=>cropsFR[s]||s;
const num=(v:unknown,d=2)=>v!==null&&v!==undefined&&String(v).trim()!==''&&Number.isFinite(Number(v))?new Intl.NumberFormat('fr-FR',{maximumFractionDigits:d}).format(Number(v)):'—';
const dateFR=(s:string|null|undefined)=>s?new Date(s).toLocaleDateString('fr-FR'):'Non documentée';
const today=()=>new Date().toISOString().slice(0,10);
const areaLabels:Record<string,string>={mixed_source_area_definitions:'Sources aux définitions de superficie différentes',cropped_area_reported_harvested_vs_planted_unresolved:'Superficie déclarée : semée ou récoltée non résolue',planted_available_harvested_unavailable:'Superficie semée (récoltée indisponible)',planted_available_harvested_not_available:'Superficie semée (récoltée indisponible)',FAOSTAT_YIELD_DEFINITION_national:'Définition nationale FAOSTAT (rendement agricole)',harveststat_area_semantics_unresolved:'Superficie déclarée, définition semée/récoltée non résolue'};
const modelLabels:Record<string,string>={ridge_log_alpha10:'Régression Ridge logarithmique (α = 10)',ridge_log_alpha100:'Régression Ridge logarithmique (α = 100)',recent_mean5:'Moyenne d’au plus cinq dernières observations',last_observation:'Dernière observation',national_pref_shrink:'Référence nationale avec ajustement préfectoral',random_forest:'Forêt aléatoire',regional_shrink:'Référence régionale avec rétrécissement',prefecture_climatology:'Moyenne historique préfectorale',damped_logtrend:'Tendance logarithmique amortie',loglinear_ridge:'Régression Ridge log-linéaire',national_only:'Référence nationale'};
const statusLabels:Record<string,string>={prevu:'Planifié',confirme:'Confirmé',partiel:'Collecte partielle',termine:'Terminé',annule:'Annulé',brouillon:'Brouillon',soumis:'Soumis',valide:'Validé'};
const observationLabel=(o:any)=>o?.comparabilityStatus==='EXCLUDED_GEOGRAPHY_UNVERIFIED'?'Observation · géographie non vérifiée':/^[XE]:/.test(o?.observationStatus||'')?'Diagnostic · exclu des scores':o?.primaryEvaluation?'Observation officielle · évaluation principale':'Observation historique';
const normalLevel=(s:string)=>s==='Préfecture historique'?'prefecture_historique':s==='National'?'national':s==='Région'?'region':s;
const levels:Record<string,string>={prefecture_historique:'Préfecture historique',prefecture:'Préfecture historique',region:'Région',national:'National'};
function Icon({name,size=20}:{name:string;size?:number}){const paths:Record<string,any>={leaf:<><path d="M19 4c-7-1-14 2-14 8a6 6 0 0 0 6 6c6 0 8-7 8-14Z"/><path d="M4 21 15 10"/></>,chart:<><path d="M4 4v16h16"/><path d="m7 15 4-5 4 3 5-7"/></>,calc:<><rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 7h8M8 11h2m4 0h2m-8 4h2m4 0h2m-8 3h2m4 0h2"/></>,truck:<><path d="M3 7h11v10H3zM14 10h4l3 4v3h-7"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/></>,basket:<><path d="m7 9 5-6 5 6M3 10h18l-2 10H5zM9 13v4m6-4v4"/></>,file:<><path d="M14 3H5v18h14V8zM14 3v5h5M8 12h8m-8 4h8"/></>,arrow:<path d="M4 12h15m-5-5 5 5-5 5"/>,download:<><path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/></>,plus:<path d="M12 5v14M5 12h14"/>,check:<path d="m4 12 5 5L20 6"/>,info:<><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/></>,users:<><circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5"/></>,settings:<><circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/></>};return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.65" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]||paths.info}</svg>}
function Field({label,children,hint}:{label:string;children:React.ReactNode;hint?:string}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Empty({children}:{children:React.ReactNode}){return <div className="empty-state"><Icon name="leaf" size={30}/><p>{children}</p></div>}
function Table({headers,children}:{headers:string[];children:React.ReactNode}){return <div className="table-wrap" tabIndex={0}><table className="data-table"><thead><tr>{headers.map(h=><th key={h} scope="col">{h}</th>)}</tr></thead><tbody>{children}</tbody></table></div>}
function Badge({children,warning=false}:{children:React.ReactNode;warning?:boolean}){return <span className={'badge'+(warning?' warning':'')}>{children}</span>}
function LineChart({observations,forecasts}:{observations:Observation[];forecasts:Forecast[]}){const data=[...observations.map(o=>({...o,type:'obs'})),...forecasts.map(f=>({...f,type:'pred'}))].sort((a,b)=>a.year-b.year);if(!data.length)return <Empty>Aucune série disponible pour ces filtres.</Empty>;const years=[...new Set(data.map(d=>d.year))].sort((a,b)=>a-b);const min=years[0],max=years[years.length-1];const ymax=Math.max(...data.map(d=>d.yield),.1)*1.18;const X=(y:number)=>62+(y-min)/(max-min||1)*690,Y=(v:number)=>235-v/ymax*195;const pts=(t:string)=>data.filter(d=>d.type===t).map(d=>`${X(d.year)},${Y(d.yield)}`).join(' ');return <div className="chart"><svg viewBox="0 0 800 290" role="img" aria-label="Évolution des rendements en tonnes par hectare. Observations en ligne continue et cercles, estimations en tirets et losanges. Les valeurs exactes figurent dans le tableau.">{[0,1,2,3,4].map(k=><g key={k}><line x1="62" x2="752" y1={Y(ymax*k/4)} y2={Y(ymax*k/4)} stroke="#e6ebe6"/><text x="48" y={Y(ymax*k/4)+4} textAnchor="end" fill="#64746b" fontSize="12">{num(ymax*k/4,1)}</text></g>)}<text x="62" y="17" fill="#64746b" fontSize="12">Rendement (t/ha)</text><polyline points={pts('obs')} fill="none" stroke="#245d48" strokeWidth="2.5"/><polyline points={pts('pred')} fill="none" stroke="#b67526" strokeWidth="2.5" strokeDasharray="7 5"/>{data.map((d,i)=>d.type==='obs'?<circle key={i} cx={X(d.year)} cy={Y(d.yield)} r="3.5" fill="#245d48"><title>{d.year} · observation : {num(d.yield,4)} t/ha</title></circle>:<path key={i} d={`M${X(d.year)} ${Y(d.yield)-5}l5 5-5 5-5-5z`} fill="#b67526"><title>{d.year} · estimation : {num(d.yield,4)} t/ha</title></path>)}{years.filter((_,i)=>i%Math.max(1,Math.ceil(years.length/10))===0||i===years.length-1).map(y=><text key={y} x={X(y)} y="260" textAnchor="middle" fill="#64746b" fontSize="12">{y}</text>)}</svg><div className="chart-legend"><span><i className="legend-dot"/> Observations historiques · trait continu</span><span><i className="legend-dash"/> Estimations du mémoire · tirets</span></div></div>}

export default function AgriApp(){
const [view,setView]=useState<View>('previsions');const [science,setScience]=useState<Science|null>(null);const [workspace,setWorkspace]=useState<Bootstrap|null>(null);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [busy,setBusy]=useState(false);const [online,setOnline]=useState(true);const [crop,setCrop]=useState('');const [year,setYear]=useState(2026);const [territory,setTerritory]=useState('');const [level,setLevel]=useState('');const [version,setVersion]=useState('');const [showAllSeries,setShowAllSeries]=useState(false);const [demoRole,setDemoRole]=useState<Role>('responsable');const [demoCoop,setDemoCoop]=useState('demo-a');
const [sim,setSim]=useState({area:'5',yield:'',source:'forecast',low:'-20',high:'20',bagWeight:'100',areaType:'recoltee',name:''});
const [editCollect,setEditCollect]=useState('');const [editCapacity,setEditCapacity]=useState('');const [collect,setCollect]=useState({memberId:'',estimated:'0',declared:'0',committed:'0',collected:'0',point:'Magasin central',date:today(),status:'prevu',harvestId:''});
const [harvest,setHarvest]=useState({memberId:'',producer:'',area:'',quantity:'',unit:'kg',bagWeight:'100',date:today(),method:'declaration',status:'brouillon',comment:'',evidence:''});const [harvestStep,setHarvestStep]=useState(1);const [editHarvest,setEditHarvest]=useState('');const [member,setMember]=useState({name:'',locality:''});const [capacity,setCapacity]=useState({storage:'',transport:'',point:'Magasin central'});const [inviteCode,setInviteCode]=useState('');const [newInviteCode,setNewInviteCode]=useState('');const [inviteRole,setInviteRole]=useState('agent');const [inviteMemberId,setInviteMemberId]=useState('');const [inviteEmail,setInviteEmail]=useState('');const [csv,setCsv]=useState('');const [importReport,setImportReport]=useState<any>(null);const [importChecked,setImportChecked]=useState(false);
async function api(path:string,options?:RequestInit){const res=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options?.headers}});let data:any;try{data=await res.json()}catch{throw new Error('Le serveur ne répond pas. Votre saisie est conservée.')}if(!res.ok)throw new Error(data.error||'Impossible de terminer cette action.');return data}
async function load(){setLoading(true);setError('');try{const s=await api('/api/science');setScience(s);setCrop(c=>c||s.forecasts.find((f:Forecast)=>f.crop==='Maize')?.crop||s.forecasts[0]?.crop||s.observations[0]?.crop||'');setTerritory(t=>t||s.forecasts[0]?.territory||s.observations[0]?.territory||'');setLevel(l=>l||normalLevel(s.forecasts[0]?.level||''));try{setWorkspace(await api('/api/workspace'))}catch{setWorkspace(null)}}catch(e){setError((e as Error).message)}finally{setLoading(false)}}
useEffect(()=>{load();setOnline(navigator.onLine);const on=()=>setOnline(true),off=()=>setOnline(false);window.addEventListener('online',on);window.addEventListener('offline',off);return()=>{window.removeEventListener('online',on);window.removeEventListener('offline',off)}},[]);
useEffect(()=>{if(notice){const t=setTimeout(()=>setNotice(''),6500);return()=>clearTimeout(t)}},[notice]);
const forecasts=science?.forecasts||[],observations=science?.observations||[];const crops=[...new Set([...forecasts,...observations].map(x=>x.crop))].sort();const territories=[...new Set([...forecasts,...observations].filter(x=>(!crop||x.crop===crop)&&(!level||normalLevel(x.level)===normalLevel(level))).map(x=>x.territory))].sort();const allLevels=[...new Set([...forecasts,...observations].map(x=>normalLevel(x.level)))];const years=[...new Set([...forecasts,...observations].map(x=>x.year))].sort((a,b)=>b-a);
const match=(r:{crop:string;territory:string;level?:string})=>(!crop||r.crop===crop)&&(!territory||r.territory===territory)&&(!level||!r.level||normalLevel(r.level)===normalLevel(level));
const seriesObs=observations.filter(match).sort((a,b)=>a.year-b.year),allSeriesPred=forecasts.filter(match).sort((a,b)=>a.year-b.year);const availableVersions=[...new Set(allSeriesPred.map(f=>f.version))];const activeVersion=availableVersions.includes(version)?version:availableVersions[0]||'';const seriesPred=allSeriesPred.filter(f=>f.version===activeVersion);const selected=seriesPred.find(x=>x.year===year);const selectedObs=seriesObs.find(x=>x.year===year);const latestObs=seriesObs[seriesObs.length-1];
const records=workspace?.records||[];const members=records.filter(r=>r.kind==='member');const inContext=(r:BusinessRecord)=>(!r.data.crop||r.data.crop===crop)&&(!r.data.year||Number(r.data.year)===year)&&(!r.data.territory||r.data.territory===territory);const sims=records.filter(r=>r.kind==='simulation'&&inContext(r));const collections=records.filter(r=>r.kind==='collection'&&inContext(r));const harvests=records.filter(r=>r.kind==='harvest'&&inContext(r));const capacities=records.filter(r=>r.kind==='capacity');
const normalized=(d:Record<string,any>)=>d.unit==='kg'?Number(d.quantity)/1000:d.unit==='sac'?Number(d.quantity)*Number(d.bagWeight)/1000:Number(d.quantity);
const sum=(rs:BusinessRecord[],field:string)=>rs.reduce((a,r)=>a+(Number(r.data[field])||0),0);const totalHarvest=harvests.filter(r=>r.data.status==='valide').reduce((a,r)=>a+normalized(r.data),0),totalArea=sum(harvests.filter(r=>r.data.status==='valide'),'area');const totals={estimated:sum(collections.filter(r=>r.data.status!=='annule'),'estimated'),declared:sum(collections.filter(r=>r.data.status!=='annule'),'declared'),committed:sum(collections.filter(r=>r.data.status!=='annule'),'committed'),collected:sum(collections.filter(r=>r.data.status!=='annule'),'collected')};const storage=sum(capacities,'storage'),transport=sum(capacities,'transport'),hasCapacity=capacities.length>0;
const retrospective:any[]=((science as any)?.comparisons||[]).filter((r:any)=>match(r)&&(!r.forecastId||seriesPred.some(f=>f.id===r.forecastId)));const pairs:{prediction:Forecast;observation:Observation;error:number}[]=retrospective.filter((r:any)=>r.compatibleForMetrics===true).map((r:any)=>({prediction:{...r,yield:r.prediction},observation:{...r,yield:r.observation},error:r.prediction-r.observation}));const retroObs:Observation[]=retrospective.map((r:any)=>({...r,yield:r.observation}));const retroPred:Forecast[]=retrospective.map((r:any)=>({...r,yield:r.prediction}));const mae=pairs.length?pairs.reduce((a,p)=>a+Math.abs(p.error),0)/pairs.length:null,rmse=pairs.length?Math.sqrt(pairs.reduce((a,p)=>a+p.error*p.error,0)/pairs.length):null,bias=pairs.length?pairs.reduce((a,p)=>a+p.error,0)/pairs.length:null;
const simYield=sim.source==='forecast'?selected?.yield:sim.yield.trim()===''?undefined:Number(sim.yield),simVolume=sim.area.trim()===''||simYield===undefined?NaN:Number(sim.area)*simYield,simLow=simVolume*(1+Number(sim.low)/100),simHigh=simVolume*(1+Number(sim.high)/100);const canManage=workspace&&['responsable','admin'].includes(workspace.session.role);const coopLabel=workspace?.session.demo?(workspace.session.coopId.startsWith('demo-b')?'Coopérative B · démonstration':'Coopérative A · démonstration'):workspace?'Mon espace coopératif':'Aucun espace ouvert';const logisticsAlerts=planningAlerts(collections.map(r=>r.data as any),capacities.map(r=>r.data as any));
async function save(kind:RecordKind,data:Record<string,any>,id?:string){if(!online){setError('Connexion perdue : reconnectez-vous puis réessayez. Votre saisie est conservée.');return false}if(!workspace){setError('Ouvrez un espace de démonstration ou connectez-vous pour enregistrer.');return false}setBusy(true);setError('');try{const result=await api('/api/workspace',{method:'POST',body:JSON.stringify({kind,data,id,updatedAt:id?records.find(r=>r.id===id)?.updatedAt:undefined})});const fresh=await api('/api/workspace');setWorkspace(fresh);setNotice(result.warnings?.length?'Enregistré. '+result.warnings.join(' '):'Enregistrement effectué.');return true}catch(e){setError((e as Error).message);return false}finally{setBusy(false)}}
async function demo(){setBusy(true);setError('');try{await api('/api/demo',{method:'POST',body:JSON.stringify({role:demoRole,coopId:demoCoop})});await load();setCollect(c=>({...c,memberId:'',harvestId:''}));setHarvest(h=>({...h,memberId:'',producer:''}));setEditCollect('');setEditHarvest('');setEditCapacity('');setNotice('Espace de démonstration ouvert. Les données métier sont fictives.')}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
const reportUrl='/api/report?'+new URLSearchParams({crop,year:String(year),territory,level,version:activeVersion});
const exportUrl=(kind:string,allYears=false)=>`/api/export?${new URLSearchParams({kind,crop,...(allYears?{}:{year:String(year)}),territory,...(['forecast','observation'].includes(kind)?{level}:{}),...(kind==='forecast'?{version:activeVersion}:{})})}`;const seriesTable=[...seriesObs.map(o=>({...o,type:observationLabel(o)})),...seriesPred.map(p=>({...p,type:'Estimation exploratoire'}))].sort((a,b)=>b.year-a.year);
function navigate(v:View){setError('');setView(v);window.scrollTo({top:0,behavior:'smooth'})}
function simulateSelected(){setSim(s=>({...s,source:'forecast',yield:String(selected?.yield||'')}));navigate('simulation')}
function recordName(id:string){return members.find(m=>m.id===id)?.data.name||'Membre non précisé'}
const context=<><strong>{fr(crop)||'Toutes les cultures'}</strong><span> · </span>{year}<span> · </span>{territory||'Territoire à choisir'}</>;
return <div className="app-shell"><aside className="sidebar no-print"><a className="brand" href="/" aria-label="AgriPrévision Togo, accueil"><span className="brand-mark"><Icon name="leaf" size={27}/></span><span>AgriPrévision<small>TOGO</small></span></a><div className="sidebar-section-label">VOTRE CAMPAGNE</div><nav aria-label="Navigation principale">{views.map((v,i)=><button key={v.id} className={'nav-item'+(view===v.id?' active':'')} onClick={()=>navigate(v.id)} aria-current={view===v.id?'page':undefined}><Icon name={v.icon}/><span>{v.label}</span><small>{String(i+1).padStart(2,'0')}</small></button>)}</nav><div className="sidebar-bottom"><button className={'nav-item'+(view==='gestion'?' active':'')} onClick={()=>navigate('gestion')}><Icon name="users"/><span>Membres et moyens</span></button><button className={'nav-item'+(view==='import'?' active':'')} onClick={()=>navigate('import')}><Icon name="settings"/><span>Sources et import</span></button><div className="sidebar-note"><span className="status-dot"/> Du mémoire au terrain<p>Un outil de recherche pour préparer et suivre les campagnes.</p><small>RÉSULTATS EXPLORATOIRES · V24</small></div></div></aside>
<main className="workspace"><header className="topbar no-print"><div><span className="eyebrow">ESPACE DE TRAVAIL AGRICOLE</span><p>{workspace?coopLabel:'Préparer la prochaine campagne'}</p></div><div className="topbar-actions"><span className="badge muted">{workspace?workspace.session.role:'Consultation'}</span><span className="avatar">{workspace?.session.name?.slice(0,1)||'A'}</span></div></header>
<div className="page-content">
{!online&&<div role="alert" className="notice warning">Vous êtes hors connexion. Les résultats déjà chargés restent consultables. Les enregistrements attendent votre reconnexion.</div>}
{notice&&<div role="status" className="toast"><Icon name="check"/>{notice}</div>}
{error&&<div role="alert" className="notice warning">{error} <button className="btn small secondary" onClick={load}>Réessayer le chargement</button></div>}
{loading?<div className="card empty-state" role="status">Chargement des résultats du mémoire…</div>:<>
<div className="page-heading"><div><span className="eyebrow">{view==='previsions'?'COMPRENDRE POUR PRÉPARER':view==='comparaison'?'REPLACER LES CHIFFRES DANS LE TEMPS':view==='simulation'?'DU RENDEMENT AU VOLUME':view==='collecte'?'DES VOLUMES À L’ORGANISATION':view==='recoltes'?'LE TERRAIN COMME POINT DE REPÈRE':view==='fiche'?'UNE CAMPAGNE, UNE VUE D’ENSEMBLE':view==='import'?'TRAÇABILITÉ SCIENTIFIQUE':'VOTRE COMMUNAUTÉ'}</span><h1>{views.find(v=>v.id===view)?.label||(view==='import'?'Sources et intégration':'Membres et moyens')}</h1><p>{view==='previsions'?'Explorez les estimations du mémoire et les observations disponibles.':view==='comparaison'?'Distinguez les observations des estimations, puis examinez les écarts compatibles.':view==='simulation'?'Transformez un rendement en hypothèse de récolte, avec vos propres superficies.':view==='collecte'?'Préparez les créneaux, les points de passage et les capacités nécessaires.':view==='recoltes'?'Conservez les quantités déclarées ou mesurées et l’historique des corrections.':view==='fiche'?'Retrouvez les hypothèses, les réalisations et les limites de votre campagne.':view==='import'?'Chaque résultat garde sa source et sa version. Les imports restent indépendants des récoltes.':'Renseignez les membres de la coopérative et les capacités disponibles.'}</p></div><div className="page-actions no-print">{view==='previsions'&&<button className="btn primary" onClick={simulateSelected} disabled={!selected}>Simuler une récolte <Icon name="arrow" size={17}/></button>}{view==='fiche'&&<a className="btn primary" href={reportUrl}><Icon name="download" size={17}/> Télécharger le PDF</a>}</div></div>
{(!workspace||view==='gestion')&&<section className="card demo-panel no-print"><div className="card-header"><div><span className="eyebrow">DÉMONSTRATION SANS DONNÉES PERSONNELLES</span><h2>{workspace?'Changer de rôle de démonstration':'Ouvrir un espace de travail'}</h2><p>Les prévisions viennent du travail scientifique; seuls les membres et les activités de cet espace sont fictifs.</p></div></div><div className="form-grid"><Field label="Rôle de démonstration"><select value={demoRole} onChange={e=>setDemoRole(e.target.value as Role)}><option value="responsable">Responsable de coopérative</option><option value="agent">Agent agricole</option><option value="producteur">Producteur</option><option value="admin">Administrateur</option></select></Field><Field label="Coopérative fictive"><select value={demoCoop} onChange={e=>setDemoCoop(e.target.value)}><option value="demo-a">Coopérative A · démonstration</option><option value="demo-b">Coopérative B · démonstration</option></select></Field></div><div className="form-actions"><button className="btn primary" disabled={busy} onClick={demo}>Ouvrir la démonstration <Icon name="arrow" size={17}/></button><a className="btn secondary" href="/signin-with-chatgpt?return_to=%2F" target="_top">Se connecter avec ChatGPT</a></div></section>}
{!['gestion','import'].includes(view)&&<section className="filter-bar no-print" aria-label="Contexte de campagne"><label className="filter-field"><span>Culture</span><select value={crop} onChange={e=>{setCrop(e.target.value);const ts=[...forecasts,...observations].filter(x=>x.crop===e.target.value&&(!level||normalLevel(x.level)===normalLevel(level))).map(x=>x.territory);if(!ts.includes(territory))setTerritory(ts[0]||'')}}>{crops.map(c=><option key={c} value={c}>{fr(c)}</option>)}</select></label><label className="filter-field"><span>Campagne</span><select value={year} onChange={e=>setYear(Number(e.target.value))}>{years.map(y=><option key={y}>{y}</option>)}</select></label><label className="filter-field"><span>Territoire</span><select value={territory} onChange={e=>setTerritory(e.target.value)}>{territories.map(t=><option key={t}>{t}</option>)}</select></label><label className="filter-field"><span>Échelle géographique</span><select value={level} onChange={e=>{const next=e.target.value;setLevel(next);const ts=[...forecasts,...observations].filter(x=>x.crop===crop&&normalLevel(x.level)===normalLevel(next)).map(x=>x.territory);if(!ts.includes(territory))setTerritory(ts.includes('Togo')?'Togo':ts.sort()[0]||'')}}>{allLevels.map(l=><option key={l} value={l}>{levels[l]||l}</option>)}</select></label><label className="filter-field"><span>Version des estimations</span><select value={activeVersion} onChange={e=>setVersion(e.target.value)}>{availableVersions.length?availableVersions.map(v=><option key={v} value={v}>{v}</option>):<option value="">Aucune estimation</option>}</select></label></section>}
{view==='previsions'&&<><div className="notice info"><Icon name="info"/><div><strong>Des estimations exploratoires, à interpréter avec précaution.</strong><p>{selected?.version===science?.meta.version?'Le protocole v24 est reproduit à origine fixe 2015. Son CSV correspond exactement à l’empreinte du notebook exécuté. Ces estimations ne sont pas actualisées par les récoltes récentes et ne sont pas validées pour une parcelle.':'Version importée : consultez sa source, sa date d’émission et son statut déclaré. L’import technique ne constitue pas une validation scientifique ni une validation parcellaire.'}</p></div><Badge warning>{selected?.version||'Recherche · v24'}</Badge></div><section className="stat-grid"><article className="stat-card featured"><div className="stat-label">Rendement estimé · {year}</div><div className="stat-value">{selected?num(selected.yield,3):'—'} <span className="stat-unit">t/ha</span></div><div><Badge warning>{(selected as any)?.originYear?'Rétrospectif · origine '+(selected as any).originYear:year<new Date().getFullYear()?'Estimation historique':'Exploratoire'}</Badge></div><p>{selected?`${fr(crop)} · ${territory}`:'Aucune prévision disponible pour cette campagne.'}</p></article><article className="stat-card"><div className="stat-label">Dernière observation disponible</div><div className="stat-value">{latestObs?num(latestObs.yield,3):'—'} <span className="stat-unit">t/ha</span></div><p>{latestObs?`Campagne ${latestObs.year} · ${latestObs.source}`:'Aucune observation disponible.'}</p>{latestObs&&<Badge warning={!(latestObs as any)?.primaryEvaluation}>{observationLabel(latestObs)}</Badge>}<small>Une observation ancienne ne décrit pas la campagne actuelle.</small></article><article className="stat-card"><div className="stat-label">Portée du résultat</div><h3>{levels[selected?.level||level]||level||'Non précisée'}</h3><p>{normalLevel(selected?.level||level)==='national'?'Estimation pour l’ensemble du Togo. Elle ne décrit pas chaque localité ni chaque parcelle.':'Grille géographique historique. La validité des correspondances administratives actuelles reste à établir.'}</p><small>Aucune précision parcellaire déduite.</small></article></section><div className="split-grid"><section className="card"><div className="card-header"><div><span className="eyebrow">REPÈRES HISTORIQUES</span><h2>Le rendement au fil des campagnes</h2></div><button className="btn secondary small" onClick={()=>navigate('comparaison')}>Comparer <Icon name="arrow" size={15}/></button></div><LineChart observations={seriesObs} forecasts={seriesPred}/><p className="source-note">{selected?.version===science?.meta.version?'Origine des calculs v24 : 2015. La méthode sélectionnée peut varier avec l’horizon; une rupture de la courbe ne traduit pas automatiquement une évolution agronomique attendue. Aucune donnée récente ne réactualise ces estimations.':'La série affichée utilise la version choisie dans les filtres. Sa source et sa portée restent celles déclarées lors de l’import.'} Les observations locales après 2015 dont la correspondance géographique est non vérifiée restent descriptives.</p></section><aside className="card"><span className="eyebrow">CE QUE DIT CE CHIFFRE</span><h2>Lire l’estimation</h2><dl className="summary-list"><dt>Méthode</dt><dd>{modelLabels[selected?.model||'']||selected?.model||'Indisponible'}</dd><dt>Version</dt><dd>{selected?.version||'Non disponible'}</dd><dt>Date de reproduction du calcul</dt><dd>{selected?.issuedAt?dateFR(selected.issuedAt):'Date non documentée dans la sortie disponible'}</dd>{(selected as any)?.originYear&&<><dt>Dernière année admise pour le calcul</dt><dd>{(selected as any).originYear}</dd></>}{(selected as any)?.decisionDate&&<><dt>Date de décision du protocole</dt><dd>{dateFR((selected as any).decisionDate)}</dd></>}<dt>Définition de superficie</dt><dd>{areaLabels[selected?.areaDefinition||'']||selected?.areaDefinition||'Voir provenance du résultat'}</dd></dl><p className="source-note">{selected?.source||science?.meta.sourceDescription}</p></aside></div><section className="card"><div className="card-header"><div><h2>La série disponible</h2><p>Toutes les campagnes · {activeVersion} · {fr(crop)} · {territory}</p></div><div className="page-actions no-print"><a className="btn secondary small" href={exportUrl('forecast',true)}><Icon name="download" size={16}/> Estimations · série CSV</a><a className="btn secondary small" href={exportUrl('observation',true)}>Observations · série CSV</a><a className="btn secondary small" href={exportUrl('forecast')}>Campagne {year} · CSV</a></div></div><Table headers={['Campagne','Type de donnée','Rendement (t/ha)','Territoire','Origine']} >{(showAllSeries?seriesTable:seriesTable.slice(0,12)).map((r,i)=><tr key={r.id+'-'+i}><td>{r.year}</td><td><Badge warning={r.type.includes('Diagnostic')||r.type.includes('non vérifiée')||r.type==='Estimation exploratoire'}>{r.type}</Badge></td><td>{num(r.yield,4)}</td><td>{r.territory}</td><td>{r.source}</td></tr>)}</Table>{seriesTable.length>12&&<div className="form-actions no-print"><span className="source-note">{showAllSeries?seriesTable.length:12} ligne(s) affichée(s) sur {seriesTable.length}.</span><button className="btn secondary small" onClick={()=>setShowAllSeries(!showAllSeries)}>{showAllSeries?'Réduire la série':'Voir toute la série'}</button></div>}</section></>}
{view==='comparaison'&&<><section className="card"><div className="card-header"><div><h2>Évaluation rétrospective du système v24</h2><p>{fr(crop)} · {territory} · toutes les campagnes disponibles</p></div></div><LineChart observations={retroObs} forecasts={retroPred}/><p className="source-note">Prévisions à origine fixe 2015 confrontées aux observations nationales FAOSTAT. Les campagnes 2016–2022 constituent l’évaluation principale; 2023–2024 restent des diagnostics exclus des scores. Cette évaluation rétrospective n’est pas un nouveau test aveugle. Les traits et symboles distinguent les séries sans dépendre uniquement de la couleur.</p></section><div className="stat-grid"><article className="stat-card"><div className="stat-label">Paires compatibles</div><div className="stat-value">{pairs.length}</div><p>{pairs.length?`${Math.min(...pairs.map(p=>p.prediction.year))}–${Math.max(...pairs.map(p=>p.prediction.year))}`:'Aucune année commune avec une définition de superficie identique.'}</p></article><article className="stat-card"><div className="stat-label">Erreur absolue moyenne · MAE</div><div className="stat-value">{mae===null?'—':num(mae,3)} <span className="stat-unit">t/ha</span></div><p>RMSE : {rmse===null?'non calculable':num(rmse,3)+' t/ha'}</p></article><article className="stat-card"><div className="stat-label">Biais moyen</div><div className="stat-value">{bias===null?'—':num(bias,3)} <span className="stat-unit">t/ha</span></div><p>Prévision − observation. Positif : surestimation.</p></article></div><div className="notice info"><Icon name="info"/><p>Une erreur n’est calculée que pour une année, une culture, un territoire, une échelle et une définition de superficie compatibles. Les statistiques nationales diagnostiques et les observations locales non validées géographiquement sont exclues des scores : {retrospective.length-pairs.length} paire(s) exclue(s).</p></div><section className="card"><h2>Comparaison par campagne</h2>{!retrospective.length&&<Empty>Aucune paire validée pour cette culture, cette échelle, ce territoire et cette version. Les résultats préfectoraux ne sont pas évalués contre les observations locales après 2015.</Empty>}<Table headers={['Année','Observation (t/ha)','Estimation (t/ha)','Erreur signée','Erreur absolue','Écart relatif']} >{([...new Set(retrospective.map((x:any)=>x.year))] as number[]).sort((a,b)=>b-a).map(y=>{const o=retroObs.find(x=>x.year===y),p=retroPred.find(x=>x.year===y),pair=pairs.find(x=>x.prediction.year===y);return <tr key={y}><td>{y}</td><td>{o?num(o.yield,4):'Donnée absente'}</td><td>{p?num(p.yield,4):'Donnée absente'}</td><td>{pair?num(pair.error,4)+' t/ha':'Non comparable'}</td><td>{pair?num(Math.abs(pair.error),4)+' t/ha':'—'}</td><td>{pair?(pair.observation.yield===0?'Indéfini : observation nulle':num(pair.error/pair.observation.yield*100,2)+' %'):'—'}</td></tr>})}</Table></section></>}
{view==='simulation'&&<><div className="split-grid"><section className="card"><span className="eyebrow">1 · DÉFINIR LES HYPOTHÈSES</span><h2>Votre scénario de récolte</h2><form onSubmit={async e=>{e.preventDefault();if(sim.source==='forecast'&&!selected){setError('Choisissez une campagne avec une estimation ou saisissez votre hypothèse.');return}await save('simulation',{crop,year,territory,area:Number(sim.area),yield:simYield,forecastId:sim.source==='forecast'?selected?.id:undefined,source:sim.source,scenarioLow:(simYield||0)*(1+Number(sim.low)/100),scenarioHigh:(simYield||0)*(1+Number(sim.high)/100),bagWeight:Number(sim.bagWeight),areaType:sim.areaType,name:sim.name,productionT:simVolume})}}><div className="form-grid"><Field label="Origine du rendement"><select value={sim.source} onChange={e=>setSim({...sim,source:e.target.value})}><option value="forecast">Estimation disponible du mémoire</option><option value="personal">Hypothèse personnelle</option></select></Field><Field label="Rendement central (t/ha)"><input type="number" min="0" step="any" required disabled={sim.source==='forecast'} value={sim.source==='forecast'?(selected?.yield??''):sim.yield} onChange={e=>setSim({...sim,yield:e.target.value})}/></Field><Field label="Superficie (hectares)"><input type="number" min="0.000001" step="any" required value={sim.area} onChange={e=>setSim({...sim,area:e.target.value})}/></Field><Field label="Type de superficie"><select value={sim.areaType} onChange={e=>setSim({...sim,areaType:e.target.value})}><option value="recoltee">Superficie effectivement récoltée</option><option value="semee">Superficie semée</option><option value="prevue">Superficie prévue</option></select></Field><Field label="Variante basse (%)" hint="Variation choisie, à partir du volume central."><input type="number" min="-100" max="0" step="any" required value={sim.low} onChange={e=>setSim({...sim,low:e.target.value})}/></Field><Field label="Variante haute (%)"><input type="number" min="0" max="1000" step="any" required value={sim.high} onChange={e=>setSim({...sim,high:e.target.value})}/></Field><Field label="Poids d’un sac (kg)"><input type="number" min="0.001" step="any" required value={sim.bagWeight} onChange={e=>setSim({...sim,bagWeight:e.target.value})}/></Field><Field label="Nom du scénario (facultatif)"><input value={sim.name} onChange={e=>setSim({...sim,name:e.target.value})} placeholder="Par exemple : groupe de producteurs Nord" maxLength={100}/></Field></div><div className="notice warning"><p>Hypothèse locale : ce rendement territorial n’est pas validé pour votre parcelle. Sa définition de superficie peut être semée ou non résolue; la multiplication suppose sa compatibilité avec vos hectares. Modifier la superficie ne modifie pas le rendement.</p></div><div className="form-actions"><button className="btn primary" disabled={busy||simYield===undefined||!Number.isFinite(simYield)} type="submit"><Icon name="plus" size={17}/> Enregistrer la simulation</button></div></form></section><aside className="card simulation-result"><span className="eyebrow">2 · LIRE LE VOLUME</span><h2>Une hypothèse, trois scénarios</h2><p>{num(simYield,3)} t/ha × {num(sim.area)} ha</p><div className="stat-value">{num(simVolume,3)} <span className="stat-unit">tonnes</span></div><p>Scénario central</p><dl className="summary-list"><dt>Variante basse · {sim.low} %</dt><dd>{num(simLow,3)} t</dd><dt>Variante haute · +{sim.high} %</dt><dd>{num(simHigh,3)} t</dd><dt>Conversion</dt><dd>{num(simVolume*1000,1)} kg</dd><dt>Sacs équivalents de {num(sim.bagWeight)} kg</dt><dd>{Number(sim.bagWeight)>0?num(simVolume*1000/Number(sim.bagWeight),1):'—'}</dd></dl><p className="source-note">Ces variantes sont choisies par l’utilisateur. Elles ne sont ni des probabilités ni des intervalles de confiance.</p><button className="btn secondary" onClick={()=>{setCollect({...collect,estimated:String(simVolume)});navigate('collecte')}}>Préparer la collecte <Icon name="arrow" size={17}/></button></aside></div><section className="card"><h2>Simulations enregistrées</h2>{!sims.length?<Empty>Aucune simulation enregistrée pour ce contexte.</Empty>:<Table headers={['Scénario','Superficie','Rendement','Volume central','Origine','Enregistré le']}>{sims.map(r=><tr key={r.id}><td>{r.data.name||'Simulation'}</td><td>{num(r.data.area)} ha</td><td>{num(r.data.yield,4)} t/ha</td><td>{num(Number(r.data.area)*Number(r.data.yield),3)} t</td><td>{r.data.forecastId?'Estimation du mémoire, version conservée':'Hypothèse personnelle'}</td><td>{dateFR(r.createdAt)}</td></tr>)}</Table>}</section></>}
{view==='collecte'&&<><div className="notice info"><Icon name="info"/><p>Chaque ligne suit une même récolte. Estimation, déclaration, engagement et collecte sont des étapes distinctes : leurs volumes ne s’additionnent pas.</p></div><section className="stat-grid four">{[['estimated','Estimé'],['declared','Déclaré'],['committed','Engagé'],['collected','Collecté']].map(([k,l])=><article className="stat-card" key={k}><div className="stat-label">{l}</div><div className="stat-value">{num(totals[k as keyof typeof totals],2)} <span className="stat-unit">t</span></div></article>)}</section>{logisticsAlerts.length>0&&<div className="notice warning" role="alert"><div><strong>Capacités à vérifier</strong>{logisticsAlerts.map((message,i)=><p key={i}>{message}</p>)}</div></div>}<div className="split-grid"><section className="card"><h2>{editCollect?'Mettre à jour le passage':'Planifier un passage'}</h2><form onSubmit={async e=>{e.preventDefault();const saved=await save('collection',{...collect,date:collect.date.slice(0,10),slotHHmm:collect.date.includes('T')?collect.date.slice(11,16):'08:00',crop,year,territory,estimated:Number(collect.estimated),declared:Number(collect.declared),committed:Number(collect.committed),collected:Number(collect.collected)},editCollect||undefined);if(saved)setEditCollect('')}}><div className="form-grid"><Field label="Membre concerné"><select required value={collect.memberId} onChange={e=>setCollect({...collect,memberId:e.target.value})}><option value="">Choisir un membre</option>{members.map(m=><option key={m.id} value={m.id}>{m.data.name}</option>)}</select></Field><Field label="Récolte liée (facultatif)"><select value={collect.harvestId} onChange={e=>setCollect({...collect,harvestId:e.target.value})}><option value="">Aucune récolte encore saisie</option>{harvests.map(h=><option key={h.id} value={h.id}>{h.data.producer||recordName(h.data.memberId)} · {num(normalized(h.data))} t</option>)}</select></Field>{(['estimated','declared','committed','collected'] as const).map((k,i)=><Field key={k} label={['Volume estimé (t)','Quantité déclarée (t)','Engagement (t)','Quantité collectée (t)'][i]}><input type="number" min="0" step="any" required value={collect[k]} onChange={e=>setCollect({...collect,[k]:e.target.value})}/></Field>)}<Field label="Point de collecte"><input required value={collect.point} onChange={e=>setCollect({...collect,point:e.target.value})}/></Field><Field label="Créneau de collecte"><input type="datetime-local" required value={collect.date.length===10?collect.date+'T08:00':collect.date} onChange={e=>setCollect({...collect,date:e.target.value})}/></Field><Field label="Statut"><select value={collect.status} onChange={e=>setCollect({...collect,status:e.target.value})}><option value="prevu">Planifié</option><option value="confirme">Confirmé</option><option value="partiel">Collecte partielle</option><option value="termine">Terminé</option><option value="annule">Annulé</option></select></Field></div><div className="form-actions"><button className="btn primary" disabled={busy}>{editCollect?'Mettre à jour le passage':'Enregistrer le passage'}</button>{editCollect&&<button type="button" className="btn secondary" onClick={()=>setEditCollect('')}>Annuler la correction</button>}</div></form></section><aside className="card"><span className="eyebrow">PLANIFICATION MANUELLE ASSISTÉE</span><h2>Les moyens disponibles</h2><dl className="summary-list"><dt>Stockage renseigné</dt><dd>{hasCapacity?num(storage)+' t':'Non renseigné'}</dd><dt>Transport par créneau</dt><dd>{hasCapacity?num(transport)+' t':'Non renseigné'}</dd></dl><p>Ces capacités sont renseignées par la coopérative. Elles n’incluent pas automatiquement les autres campagnes.</p><button className="btn secondary" onClick={()=>navigate('gestion')}>Renseigner les moyens</button><hr/><h3>Préparer le terrain</h3><p>Confirmez avec chaque membre le volume, le point et le créneau. Le système ne propose aucun itinéraire ni allocation automatique.</p><button className="btn secondary" onClick={()=>navigate('recoltes')}>Enregistrer une récolte <Icon name="arrow" size={17}/></button></aside></div><section className="card"><div className="card-header"><h2>Plan de collecte</h2><a className="btn secondary small" href={exportUrl('collection')}>Exporter le CSV</a></div>{!collections.length?<Empty>Aucun passage planifié pour cette campagne.</Empty>:<Table headers={['Membre','Créneau et point','Estimé','Déclaré','Engagé','Collecté','Statut / action']}>{collections.map(r=><tr key={r.id}><td>{recordName(r.data.memberId)}</td><td>{dateFR(r.data.date)} · {r.data.slotHHmm||'08:00'}<br/>{r.data.point}</td><td>{num(r.data.estimated)} t</td><td>{num(r.data.declared)} t</td><td>{num(r.data.committed)} t</td><td>{num(r.data.collected)} t</td><td><Badge>{statusLabels[r.data.status]||r.data.status}</Badge><button className="btn secondary small" onClick={()=>{setCollect({...r.data,memberId:r.data.memberId,estimated:String(r.data.estimated),declared:String(r.data.declared),committed:String(r.data.committed),collected:String(r.data.collected),point:r.data.point,date:r.data.date+'T'+(r.data.slotHHmm||'08:00'),status:r.data.status,harvestId:r.data.harvestId||''});setEditCollect(r.id);window.scrollTo({top:0,behavior:'smooth'})}}>Mettre à jour</button></td></tr>)}</Table>}</section></>}
{view==='recoltes'&&<><div className="split-grid"><section className="card"><div className="card-header"><div><span className="eyebrow">ÉTAPE {harvestStep} SUR 3</span><h2>{editHarvest?'Corriger une récolte':'Déclarer une récolte'}</h2></div><Badge>Donnée communautaire</Badge></div><div className="tabs" aria-label="Étapes de déclaration">{['Identité','Quantités','Vérification'].map((s,i)=><button className={'tab'+(harvestStep===i+1?' active':'')} key={s} onClick={()=>setHarvestStep(i+1)}>{i+1}. {s}</button>)}</div><form onSubmit={async e=>{e.preventDefault();if(harvestStep<3){setHarvestStep(harvestStep+1);return}const saved=await save('harvest',{...harvest,crop,year,territory,area:Number(harvest.area),quantity:Number(harvest.quantity),bagWeight:Number(harvest.bagWeight)},editHarvest||undefined);if(saved){setHarvestStep(1);setEditHarvest('');setHarvest({...harvest,area:'',quantity:'',comment:'',evidence:''})}}}>
{harvestStep===1&&<div className="form-grid"><Field label="Membre producteur"><select required value={harvest.memberId} onChange={e=>setHarvest({...harvest,memberId:e.target.value,producer:recordName(e.target.value)})}><option value="">Choisir un membre</option>{members.map(m=><option key={m.id} value={m.id}>{m.data.name} · {m.data.locality}</option>)}</select></Field><Field label="Nom du déclarant / producteur"><input required value={harvest.producer} onChange={e=>setHarvest({...harvest,producer:e.target.value})}/></Field><Field label="Date de récolte"><input type="date" max={today()} required value={harvest.date} onChange={e=>setHarvest({...harvest,date:e.target.value})}/></Field><Field label="Comment la quantité a-t-elle été obtenue ?"><select value={harvest.method} onChange={e=>setHarvest({...harvest,method:e.target.value})}><option value="declaration">Déclaration du producteur</option><option value="measure">Mesure / pesée</option></select></Field><p className="source-note">Culture, campagne et territoire proviennent des filtres : {context}.</p></div>}
{harvestStep===2&&<div className="form-grid"><Field label="Superficie effectivement récoltée (ha)"><input type="number" min="0.000001" step="any" required value={harvest.area} onChange={e=>setHarvest({...harvest,area:e.target.value})}/></Field><Field label="Quantité récoltée"><input type="number" min="0" step="any" required value={harvest.quantity} onChange={e=>setHarvest({...harvest,quantity:e.target.value})}/></Field><Field label="Unité de quantité"><select value={harvest.unit} onChange={e=>setHarvest({...harvest,unit:e.target.value})}><option value="kg">Kilogrammes (kg)</option><option value="t">Tonnes (t)</option><option value="sac">Sacs</option></select></Field>{harvest.unit==='sac'&&<Field label="Poids d’un sac (kg)"><input type="number" min="0.001" step="any" required value={harvest.bagWeight} onChange={e=>setHarvest({...harvest,bagWeight:e.target.value})}/></Field>}<Field label="Commentaire (facultatif)"><textarea value={harvest.comment} onChange={e=>setHarvest({...harvest,comment:e.target.value})} rows={3}/></Field><Field label="Référence du justificatif (facultatif)" hint="Référence de pesée ou lien vers un document existant. Aucun téléversement dans cette version."><input value={harvest.evidence} onChange={e=>setHarvest({...harvest,evidence:e.target.value})}/></Field></div>}
{harvestStep===3&&<><dl className="summary-list"><dt>Producteur</dt><dd>{harvest.producer||'Non renseigné'}</dd><dt>Contexte</dt><dd>{context}</dd><dt>Surface récoltée</dt><dd>{num(harvest.area)} ha</dd><dt>Production normalisée</dt><dd>{num(normalized(harvest),3)} t</dd><dt>Rendement calculé</dt><dd>{Number(harvest.area)>0?num(normalized(harvest)/Number(harvest.area),3):'—'} t/ha</dd><dt>Obtention</dt><dd>{harvest.method==='measure'?'Mesure / pesée':'Déclaration'}</dd></dl><Field label="État de la fiche"><select value={harvest.status} onChange={e=>setHarvest({...harvest,status:e.target.value})}><option value="brouillon">Brouillon</option><option value="soumis">Soumis pour validation</option>{workspace&&['admin','responsable','agent'].includes(workspace.session.role)&&<option value="valide">Validé par la coopérative</option>}</select></Field><div className="notice info"><p>Cette récolte reste une donnée communautaire. Sa validation par la coopérative ne la transforme pas en statistique officielle ni en donnée d’entraînement du modèle.</p></div></>}
<div className="form-actions">{harvestStep>1&&<button type="button" className="btn secondary" onClick={()=>setHarvestStep(harvestStep-1)}>Précédent</button>}<button className="btn primary" disabled={busy}>{harvestStep<3?'Continuer':'Enregistrer la récolte'} <Icon name="arrow" size={17}/></button>{editHarvest&&<button type="button" className="btn secondary" onClick={()=>{setEditHarvest('');setHarvestStep(1)}}>Annuler la correction</button>}</div></form></section><aside className="card"><span className="eyebrow">OBSERVATIONS VALIDÉES</span><h2>Le bilan du terrain</h2><div className="stat-value">{num(totalHarvest,3)} <span className="stat-unit">t</span></div><p>sur {num(totalArea)} ha récoltés</p><dl className="summary-list"><dt>Fiches validées</dt><dd>{harvests.filter(h=>h.data.status==='valide').length}</dd><dt>Rendement agrégé</dt><dd>{totalArea>0?num(totalHarvest/totalArea,3)+' t/ha':'Non calculable'}</dd></dl><p className="source-note">Production totale divisée par la superficie totale compatible. Aucun calcul par moyenne simple des rendements individuels.</p></aside></div><section className="card"><div className="card-header"><h2>Récoltes de la campagne</h2><a href={exportUrl('harvest')} className="btn secondary small">Exporter le CSV</a></div>{!harvests.length?<Empty>Aucune récolte enregistrée dans ce contexte.</Empty>:<Table headers={['Producteur','Récolte','Superficie','Rendement','État','Historique et correction']}>{harvests.map(r=><tr key={r.id}><td>{r.data.producer||recordName(r.data.memberId)}<br/><small>{dateFR(r.data.date)} · {r.data.method==='measure'?'Mesurée':'Déclarée'}</small></td><td>{num(normalized(r.data),3)} t</td><td>{num(r.data.area)} ha</td><td>{Number(r.data.area)>0?num(normalized(r.data)/Number(r.data.area),3):'—'} t/ha</td><td><Badge>{statusLabels[r.data.status]||r.data.status}</Badge></td><td><button className="btn secondary small" onClick={()=>{setHarvest({...harvest,...r.data,area:String(r.data.area),quantity:String(r.data.quantity),bagWeight:String(r.data.bagWeight||100)});setEditHarvest(r.id);setHarvestStep(1);window.scrollTo({top:0,behavior:'smooth'})}}>Corriger</button><details><summary>{r.history?.length||0} correction(s)</summary><pre>{JSON.stringify(r.history||[],null,2)}</pre></details></td></tr>)}</Table>}</section></>}
{view==='fiche'&&<section className="campaign-sheet"><div className="card"><div className="card-header"><div><span className="eyebrow">AGRIPRÉVISION TOGO · FICHE DE CAMPAGNE</span><h2>{fr(crop)} · campagne {year}</h2><p>{territory} · {levels[level]||level}</p></div><Badge warning>{workspace?.session.demo?'Coopérative fictive':'Espace communautaire'}</Badge></div><p>Générée le {new Date().toLocaleString('fr-FR')} · {coopLabel}</p><section className="stat-grid four"><article className="stat-card"><div className="stat-label">Producteurs concernés</div><div className="stat-value">{new Set([...collections,...harvests].map(r=>r.data.memberId).filter(Boolean)).size}</div></article><article className="stat-card"><div className="stat-label">Surface récoltée validée</div><div className="stat-value">{num(totalArea)} <span className="stat-unit">ha</span></div></article><article className="stat-card"><div className="stat-label">Récolte observée validée</div><div className="stat-value">{num(totalHarvest,3)} <span className="stat-unit">t</span></div></article><article className="stat-card"><div className="stat-label">Rendement agrégé communautaire</div><div className="stat-value">{totalArea>0?num(totalHarvest/totalArea,3):'—'} <span className="stat-unit">t/ha</span></div></article></section><h3>Hypothèses et résultats de référence</h3><p>{selected?`Estimation territoriale : ${num(selected.yield,4)} t/ha, méthode ${selected.model}, version ${selected.version}.`:'Aucune estimation territoriale disponible pour ces filtres.'}</p><p>{selected?.source||science?.meta.sourceDescription}</p><LineChart observations={seriesObs} forecasts={seriesPred}/><h3>Volumes de la campagne</h3><Table headers={['Catégorie','Volume','Portée']}><tr><td>Simulations enregistrées</td><td>{sims.length} scénario(s)</td><td>Alternatives non additionnées</td></tr><tr><td>Estimé pour collecte</td><td>{num(totals.estimated)} t</td><td>Hypothèses de préparation</td></tr><tr><td>Déclaré pour collecte</td><td>{num(totals.declared)} t</td><td>Déclarations des membres</td></tr><tr><td>Engagé</td><td>{num(totals.committed)} t</td><td>Volume à organiser</td></tr><tr><td>Collecté</td><td>{num(totals.collected)} t</td><td>Suivi logistique</td></tr><tr><td>Récolté et validé</td><td>{num(totalHarvest,3)} t</td><td>Observations communautaires, peut recouper le collecté</td></tr></Table>{sims.length>0&&<><h3>Scénarios conservés</h3><Table headers={['Scénario','Superficie','Rendement','Volume central','Rendements bas / haut']}>{sims.map(r=><tr key={r.id}><td>{r.data.name||'Simulation'}</td><td>{num(r.data.area)} ha</td><td>{num(r.data.yield,3)} t/ha</td><td>{num(r.data.area*r.data.yield,3)} t</td><td>{num(r.data.scenarioLow,3)} / {num(r.data.scenarioHigh,3)} t/ha</td></tr>)}</Table></>}<h3>Stockage et organisation</h3><p>{hasCapacity?`${num(storage)} t de stockage renseigné`:'Stockage non renseigné'} · {hasCapacity?`${num(transport)} t de transport par créneau`:'Transport non renseigné'}. {collections.length} passage(s) planifié(s).</p>{collections.length>0&&<Table headers={['Membre','Point','Créneau','Engagé','Collecté']}>{collections.map(r=><tr key={r.id}><td>{recordName(r.data.memberId)}</td><td>{r.data.point}</td><td>{dateFR(r.data.date)} · {r.data.slotHHmm||'08:00'}</td><td>{num(r.data.committed)} t</td><td>{num(r.data.collected)} t</td></tr>)}</Table>}<h3>Écarts interprétables</h3><p>Engagé − collecté : {num(totals.committed-totals.collected)} t. Cet écart décrit le suivi logistique, pas une erreur du modèle.</p><p>La récolte communautaire locale et l’estimation d’une préfecture historique ne constituent pas automatiquement une paire scientifique comparable. Aucun score de validation locale n’est déduit.</p><div className="notice warning"><div><strong>Limites et sources</strong><p>{selected?.version===science?.meta.version?'Résultats exploratoires du notebook v24, origine fixe 2015; aucune réactualisation par des observations ultérieures.':'Résultats de la version sélectionnée et de ses sources déclarées; leur intégration ne constitue pas une validation scientifique.'} Les simulations locales reposent sur une hypothèse de transfert territorial et de compatibilité des superficies. Les variantes sont des choix utilisateur, sans intervalle statistique. Les étapes de collecte ne sont pas cumulées. Les récoltes restent communautaires.</p><p>{workspace?.session.demo?'Les membres, capacités et enregistrements de cet espace sont fictifs. Les estimations scientifiques sont issues de la reconstitution du calcul existant.':'La coopérative conserve la responsabilité des déclarations et de leur validation.'}</p><small>Notebook : {science?.meta.notebook} · SHA-256 : {science?.meta.sha256}</small></div></div><div className="form-actions no-print"><a className="btn primary" href={reportUrl}>Télécharger la fiche PDF</a><button className="btn secondary" onClick={()=>window.print()}>Imprimer cette fiche</button><a className="btn secondary" href={exportUrl('harvest')}>Récoltes en CSV</a><a className="btn secondary" href={exportUrl('collection')}>Collecte en CSV</a></div></div></section>}
{view==='gestion'&&<><div className="split-grid"><section className="card"><h2>Ajouter un membre</h2><form onSubmit={async e=>{e.preventDefault();if(await save('member',member))setMember({name:'',locality:''})}}><div className="form-grid"><Field label="Nom du membre"><input required value={member.name} onChange={e=>setMember({...member,name:e.target.value})} maxLength={120}/></Field><Field label="Localité"><input required value={member.locality} onChange={e=>setMember({...member,locality:e.target.value})} maxLength={120}/></Field></div><div className="form-actions"><button className="btn primary" disabled={busy||!canManage}>Ajouter le membre</button></div></form>{!canManage&&<p className="source-note">La gestion des membres est réservée au responsable ou à l’administrateur.</p>}</section><section className="card"><h2>Renseigner les capacités</h2><form onSubmit={async e=>{e.preventDefault();if(await save('capacity',{storage:Number(capacity.storage),transport:Number(capacity.transport),point:capacity.point},editCapacity||undefined))setEditCapacity('')}}><div className="form-grid"><Field label="Point / magasin"><input required value={capacity.point} onChange={e=>setCapacity({...capacity,point:e.target.value})}/></Field><Field label="Stockage disponible (t)"><input type="number" min="0" step="any" required value={capacity.storage} onChange={e=>setCapacity({...capacity,storage:e.target.value})}/></Field><Field label="Transport par créneau (t)"><input type="number" min="0" step="any" required value={capacity.transport} onChange={e=>setCapacity({...capacity,transport:e.target.value})}/></Field></div><div className="form-actions"><button className="btn primary" disabled={busy||!canManage}>{editCapacity?'Mettre à jour les capacités':'Enregistrer les capacités'}</button>{editCapacity&&<button className="btn secondary" type="button" onClick={()=>setEditCapacity('')}>Annuler</button>}</div></form></section></div><section className="card"><h2>Membres de la coopérative</h2>{!members.length?<Empty>Aucun membre enregistré.</Empty>:<Table headers={['Nom','Localité','Origine']}>{members.map(m=><tr key={m.id}><td>{m.data.name}</td><td>{m.data.locality}</td><td>{workspace?.session.demo?'Démonstration':'Saisie communautaire'}</td></tr>)}</Table>}</section><section className="card"><h2>Moyens renseignés</h2>{!capacities.length?<Empty>Aucune capacité renseignée. Une valeur absente n’est pas une capacité nulle.</Empty>:<Table headers={['Point','Stockage','Transport par créneau','Action']}>{capacities.map(c=><tr key={c.id}><td>{c.data.point}</td><td>{num(c.data.storage)} t</td><td>{num(c.data.transport)} t</td><td><button className="btn secondary small" disabled={!canManage} onClick={()=>{setEditCapacity(c.id);setCapacity({point:c.data.point,storage:String(c.data.storage),transport:String(c.data.transport)});window.scrollTo({top:0,behavior:'smooth'})}}>Mettre à jour</button></td></tr>)}</Table>}</section></>}
{view==='gestion'&&<section className="card"><span className="eyebrow">ÉQUIPE ET AUTORISATIONS</span><h2>Rejoindre ou inviter dans une coopérative</h2><p>Une invitation ne donne accès qu’à la coopérative de son émetteur. Le producteur est lié à son propre membre; l’agent intervient dans la coopérative attribuée.</p><div className="split-grid"><div><h3>Accepter une invitation</h3><Field label="Code reçu du responsable"><input value={inviteCode} onChange={e=>setInviteCode(e.target.value)} autoComplete="off"/></Field><div className="form-actions"><button className="btn secondary" disabled={!inviteCode||busy} onClick={async()=>{setBusy(true);setError('');try{try{await api('/api/access',{method:'POST',body:JSON.stringify({action:'accept',code:inviteCode})})}catch(e){if((e as Error).message.includes('coopérative')&&window.confirm('Cette invitation change votre coopérative active. Les données de votre ancien espace sont conservées. Continuer ?'))await api('/api/access',{method:'POST',body:JSON.stringify({action:'accept',code:inviteCode,confirmMove:true})});else throw e}await load();setNotice('Invitation acceptée. Votre nouveau périmètre est actif.')}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}>Accepter l’invitation</button></div><p className="source-note">Connexion ChatGPT requise. L’espace de démonstration ne donne aucun accès aux données réelles.</p></div><div><h3>Créer une invitation</h3><div className="form-grid"><Field label="Rôle à attribuer"><select value={inviteRole} onChange={e=>setInviteRole(e.target.value)}><option value="agent">Agent agricole</option><option value="producteur">Producteur</option></select></Field><Field label="Email destinataire (facultatif)"><input type="email" value={inviteEmail} onChange={e=>setInviteEmail(e.target.value)}/></Field>{inviteRole==='producteur'&&<Field label="Membre lié au producteur"><select value={inviteMemberId} onChange={e=>setInviteMemberId(e.target.value)}><option value="">Choisir un membre</option>{members.map(m=><option key={m.id} value={m.id}>{m.data.name}</option>)}</select></Field>}</div><div className="form-actions"><button className="btn primary" disabled={busy||!canManage||workspace?.session.demo||inviteRole==='producteur'&&!inviteMemberId} onClick={async()=>{setBusy(true);setError('');try{const r=await api('/api/access',{method:'POST',body:JSON.stringify({action:'create',role:inviteRole,memberId:inviteMemberId||undefined,email:inviteEmail||undefined})});setNewInviteCode(r.code);setNotice('Invitation créée. Copiez le code pour le transmettre vous-même.')}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}>Créer un code d’invitation</button></div>{newInviteCode&&<div className="notice info"><div><strong>Code d’invitation à conserver</strong><pre>{newInviteCode}</pre><p>Transmettez ce code uniquement à la personne concernée. Aucun email n’a été envoyé automatiquement.</p></div></div>}{workspace?.session.demo&&<p className="source-note">Les invitations réelles sont désactivées en démonstration.</p>}</div></div></section>}
{view==='import'&&<><section className="card"><span className="eyebrow">LE TRAVAIL EXISTANT COMME POINT DE DÉPART</span><h2>Provenance du socle scientifique</h2><dl className="summary-list"><dt>Notebook accessible</dt><dd>{science?.meta.notebook}</dd><dt>Intégration</dt><dd>{science?.meta.sourceDescription}</dd><dt>Estimations disponibles</dt><dd>{forecasts.length}</dd><dt>Observations disponibles</dt><dd>{observations.length}</dd><dt>Empreinte du notebook</dt><dd className="hash">{science?.meta.sha256}</dd></dl>{science?.meta.limitations?.map((l,i)=><p className="source-note" key={i}>• {l}</p>)}<p>Consulter et simuler ne relance pas le notebook. Aucun nouveau modèle n’est entraîné par l’application.</p><a href="/scientific-data.json" download className="btn secondary">Télécharger les résultats et leur provenance</a></section><section className="card"><h2>Intégrer une nouvelle version de prévisions</h2><p>Import CSV en t/ha. Un aperçu et les rejets sont présentés avant confirmation. Les versions utilisées dans une simulation existante sont conservées.</p><details><summary>Voir le format attendu et l’exemple</summary><pre>crop,year,territory,level,yield,model,version,issuedAt,status,source,areaDefinition</pre><p>Culture et territoire doivent utiliser les identifiants du référentiel. Champs requis; date d’émission ISO ou vide; statut exploratoire ou evalue_retrosp. Téléchargez un export puis gardez son en-tête pour préparer vos propres résultats, sans modifier les résultats de référence.</p><a className="btn secondary small" href={exportUrl('forecast')}>Exporter un exemple réel</a></details><Field label="Fichier CSV"><input type="file" accept=".csv,text/csv" onChange={async e=>{const f=e.target.files?.[0];if(f){setCsv(await f.text());setImportChecked(false);setImportReport(null)}}}/></Field><Field label="Contenu CSV"><textarea rows={8} value={csv} onChange={e=>{setCsv(e.target.value);setImportChecked(false);setImportReport(null)}} placeholder="Collez le contenu ou choisissez un fichier CSV."/></Field><div className="form-actions"><button className="btn secondary" disabled={!csv||busy||workspace?.session.role!=='admin'} onClick={async()=>{setBusy(true);setError('');try{const report=await api('/api/import',{method:'POST',body:JSON.stringify({csv,confirm:false})});setImportReport(report);setImportChecked(true)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}>Vérifier et prévisualiser</button><button className="btn primary" disabled={!importChecked||!!importReport?.errors?.length||busy||workspace?.session.role!=='admin'} onClick={async()=>{setBusy(true);setError('');try{const report=await api('/api/import',{method:'POST',body:JSON.stringify({csv,confirm:true})});setImportReport(report);setScience(await api('/api/science'));if(report.preview?.[0]){const f=report.preview[0];setCrop(f.crop);setYear(f.year);setTerritory(f.territory);setLevel(normalLevel(f.level));setVersion(f.version)}setNotice(`${report.imported||0} résultat(s) importé(s).`);setImportChecked(false)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}>Confirmer l’import</button></div>{workspace?.session.role!=='admin'&&<p className="source-note">L’import est réservé à l’administrateur. Le rôle administrateur de démonstration importe uniquement dans son espace fictif.</p>}{importReport&&<div><h3>Rapport de validation</h3><p>{importReport.rows} ligne(s) · {importReport.duplicates||0} doublon(s) · {importReport.errors?.length||0} rejet(s)</p>{importReport.errors?.length>0&&<Table headers={['Ligne','Problème à corriger']}>{importReport.errors.map((er:any,i:number)=><tr key={i}><td>{er.line}</td><td>{er.message}</td></tr>)}</Table>}{importReport.preview?.length>0&&<Table headers={['Culture','Campagne','Territoire','Rendement','Version']}>{importReport.preview.map((r:any,i:number)=><tr key={i}><td>{fr(r.crop)}</td><td>{r.year}</td><td>{r.territory}</td><td>{num(r.yield,4)} t/ha</td><td>{r.version}</td></tr>)}</Table>}</div>}</section></>}

<footer className="app-footer"><span>AgriPrévision Togo</span><p>Application du mémoire · Résultats exploratoires · Les décisions de terrain demandent une validation adaptée.</p><span>Fait pour préparer, observer et comparer.</span></footer>
</>}
</div></main></div>
}
